<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ApiError } from '@/api/client';
import { addObservation, approveReview, getReview, reopenSyllabus, requestCorrection, resetSyllabus, transferTeacher, verifyObservation, type ReviewDetail, type SnapshotField } from '@/api/reviews';
import { getSession } from '@/api/session';
const route = useRoute(); const router = useRouter(); const data = ref<ReviewDetail | null>(null); const error = ref<string | null>(null); const message = ref<string | null>(null); const observation = ref({ content: '', section_key: '', field_key: '' }); const selected = ref<string[]>([]); const correction = ref(''); const reopenCause = ref(''); const resetReason = ref(''); const transfer = ref({ outgoing: '', incoming: '' }); const processing = ref(false);
const revisionId = () => String(route.params.revision); const label = (value: string) => ({ en_revision: 'En revisión', correccion_solicitada: 'Corrección solicitada', aprobado: 'Aprobado', abierta: 'Abierta', respondida: 'Respondida', verificada: 'Verificada' }[value] ?? value); const format = (value: unknown): string => value === null || value === '' ? 'Sin contenido' : typeof value === 'boolean' ? (value ? 'Sí' : 'No') : typeof value === 'object' ? JSON.stringify(value) : String(value); const currentObservations = computed(() => data.value?.observations.filter((item) => item.revision_number === data.value!.revision.number && item.state === 'abierta') ?? []);
const load = async () => { try { const session = await getSession(); if (session.active_role?.code !== 'coordinador') { await router.replace('/panel'); return; } data.value = await getReview(revisionId()); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo cargar esta revisión.'; } };
const run = async (operation: () => Promise<{ message: string }>) => { try { processing.value = true; error.value = null; message.value = (await operation()).message; await load(); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo completar la operación.'; } finally { processing.value = false; } };
const storeObservation = () => run(async () => { const payload: { content: string; section_key?: string; field_key?: string } = { content: observation.value.content }; if (observation.value.section_key) payload.section_key = observation.value.section_key; if (observation.value.field_key) payload.field_key = observation.value.field_key; const result = await addObservation(revisionId(), payload); observation.value = { content: '', section_key: '', field_key: '' }; return result; });
const request = () => run(() => requestCorrection(revisionId(), { observation_ids: selected.value, justification: correction.value }));
const switchSelected = (id: string) => { selected.value = selected.value.includes(id) ? selected.value.filter((value) => value !== id) : [...selected.value, id]; };
onMounted(() => { void load(); });
</script>
<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Coordinación</p><h1>{{ data?.syllabus.subject ?? 'Revisión' }}</h1><p>{{ data?.syllabus.code }} · {{ data?.syllabus.period }} · {{ data?.syllabus.teachers.join(', ') }}</p></div><RouterLink class="back-link" to="/coordinacion/revisiones">Volver a la cola</RouterLink></header><p v-if="message" class="save-status" role="status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><template v-if="data"><section class="detail-card"><h2>Revisión {{ data.revision.number }} · {{ label(data.syllabus.state) }}</h2><p>Enviada por {{ data.revision.submitted_by }} el {{ new Date(data.revision.submitted_at).toLocaleString('es-EC') }}.</p><p v-if="data.correction_request">Corrección solicitada: {{ data.correction_request.justification }}</p><p v-if="data.reopening">Reapertura: {{ data.reopening.cause }}.</p></section><section v-for="section in data.revision.snapshot.sections" :key="section.key" class="detail-card"><h2>{{ section.title }}</h2><article v-for="block in section.blocks" :key="block.key"><h3>{{ block.title }}</h3><dl class="review-fields"><template v-for="field in block.fields" :key="field.key"><dt>{{ field.label }}</dt><dd v-if="field.rows.length === 0">{{ format(field.value) }}</dd><dd v-else><div v-for="row in field.rows" :key="row.id" class="review-row">{{ format(row.data) }}</div></dd></template></dl></article></section><section class="detail-card"><h2>Observaciones</h2><form v-if="data.revision.is_current && data.syllabus.state === 'en_revision'" class="editor-form" @submit.prevent="storeObservation"><label>Contenido<textarea v-model="observation.content" required maxlength="10000" /></label><label>Clave de sección (opcional)<input v-model="observation.section_key" /></label><label>Clave de campo (opcional)<input v-model="observation.field_key" /></label><button :disabled="processing">Registrar observación</button></form><article v-for="item in data.observations" :key="item.id" class="ai-recommendation"><label v-if="item.revision_number === data.revision.number && item.state === 'abierta'"><input type="checkbox" :checked="selected.includes(item.id)" @change="switchSelected(item.id)" /> Seleccionar para corrección</label><strong>{{ label(item.state) }} · Revisión {{ item.revision_number }}</strong><p>{{ item.content }}</p><small>{{ item.created_by }} · {{ new Date(item.observado_en).toLocaleString('es-EC') }}</small><p v-if="item.response">Respuesta: {{ item.response.content }}</p><button v-if="item.can_verify" :disabled="processing" @click="run(() => verifyObservation(item.id))">Verificar resolución</button></article><p v-if="!data.observations.length">No hay observaciones.</p></section><section v-if="data.revision.is_current" class="detail-card"><h2>Decisión de revisión</h2><form v-if="data.syllabus.state === 'en_revision'" class="editor-form" @submit.prevent="request"><label>Justificación para solicitar corrección<textarea v-model="correction" required minlength="10" /></label><button :disabled="processing || selected.length === 0">Solicitar corrección ({{ selected.length }})</button></form><button v-if="data.syllabus.state === 'en_revision'" :disabled="processing || currentObservations.length > 0" @click="run(() => approveReview(data!.revision.id))">Aprobar revisión</button><form v-if="data.syllabus.state === 'aprobado'" class="editor-form" @submit.prevent="run(() => reopenSyllabus(data!.syllabus.id, reopenCause))"><label>Motivo de reapertura<textarea v-model="reopenCause" required minlength="10" /></label><button :disabled="processing">Reabrir sílabo</button></form><form v-if="data.reset.allowed" class="editor-form" @submit.prevent="run(() => resetSyllabus(data!.syllabus.id, resetReason))"><label>Motivo de reinicio<textarea v-model="resetReason" required minlength="10" /></label><button :disabled="processing">Reiniciar borrador</button></form><form v-if="data.transfer.allowed && data.transfer.current.length" class="editor-form" @submit.prevent="run(() => transferTeacher(data!.syllabus.id, transfer.outgoing, transfer.incoming))"><label>Docente saliente<select v-model="transfer.outgoing" required><option value="">Seleccione</option><option v-for="teacher in data.transfer.current" :key="teacher.id" :value="teacher.id">{{ teacher.nombre }}</option></select></label><label>Docente entrante<select v-model="transfer.incoming" required><option value="">Seleccione</option><option v-for="teacher in data.transfer.candidates" :key="teacher.id" :value="teacher.id">{{ teacher.nombre }}</option></select></label><button :disabled="processing">Registrar relevo</button></form></section></template><p v-else-if="!error">Cargando revisión…</p></main></template>
